<?php require_once '../config.php'; login_required('superadmin'); $msg=''; if(isset($_GET['delete'])){$id=(int)$_GET['delete'];mysqli_query($conn,"DELETE FROM users WHERE id=$id AND role='admin'");$msg='Admin deleted.';} if(isset($_GET['makeuser'])){$id=(int)$_GET['makeuser'];mysqli_query($conn,"UPDATE users SET role='user' WHERE id=$id AND role='admin'");$msg='Admin changed to user.';} $rows=mysqli_query($conn,"SELECT id,name,email,mobile FROM users WHERE role='admin' ORDER BY id DESC");?><!doctype html><html><head><title>Admins</title><link rel="stylesheet" href="../assets/css/superadmin/sidebar.css">
<link rel="stylesheet" href="../assets/css/superadmin/admins.css"></head><body><div class="layout"><?php include 'sidebar.php';?><main class="main"><h1>Manage Admins</h1><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><div class="panel"><table><tr><th>Name</th><th>Email</th><th>Mobile</th><th>Action</th></tr><?php while($r=mysqli_fetch_assoc($rows)):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['mobile'])?></td><td><a class="btn small" href="?makeuser=<?=$r['id']?>">Make User</a> <a class="btn small danger" onclick="return confirm('Delete admin?')" href="?delete=<?=$r['id']?>">Delete</a></td></tr><?php endwhile;?></table></div></main></div></body></html>
